import java.util.*;
import java.io.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;

    // Reads the next whitespace-separated token from stdin
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
        return st.nextToken();
    }

    static int nextInt() throws IOException { return Integer.parseInt(next()); }

    // Reads an r x c grid of ints
    static int[][] readGrid(int r, int c) throws IOException {
        int[][] g = new int[r][c];
        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++) g[i][j] = nextInt();
        return g;
    }

    // Prints a grid, one row per line, values separated by spaces
    static void printGrid(int[][] g, StringBuilder sb) {
        for (int[] row : g) {
            for (int j = 0; j < row.length; j++) {
                if (j > 0) sb.append(' ');
                sb.append(row[j]);
            }
            sb.append('\n');
        }
    }

    public static void main(String[] args) throws IOException {
        int r = nextInt(), c = nextInt();
        int[][] m = readGrid(r, c);
        StringBuilder sb = new StringBuilder();
        for (int j = 0; j < c; j++) {         // each column becomes a row
            for (int i = 0; i < r; i++) {
                if (i > 0) sb.append(' ');
                sb.append(m[i][j]);
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }
}

